create table public.candidate_data_gap_evaluations(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references public.jackpot_candidates(id),source_revision integer not null,result_revision integer,candidate_cutoff_at timestamptz not null,evaluated_at timestamptz not null,closure_version text not null,gap_statuses jsonb not null,evidence_refs jsonb not null default'[]',provider_errors jsonb not null default'[]',closure_hash text not null unique,created_at timestamptz not null default now());
create or replace function public.prevent_data_gap_evaluation_mutation()returns trigger language plpgsql as $$begin raise exception'Data gap evaluations are immutable';end$$;create trigger data_gap_evaluations_immutable before update or delete on public.candidate_data_gap_evaluations for each row execute function public.prevent_data_gap_evaluation_mutation();alter table public.candidate_data_gap_evaluations enable row level security;create policy "public read data gap evaluations" on public.candidate_data_gap_evaluations for select using(true);grant select on public.candidate_data_gap_evaluations to anon,authenticated;grant all on public.candidate_data_gap_evaluations to service_role;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx','qualification','data_gap_closure'));
